Select Distinct ost_ticket.ticket_id As TicketNumber,  ost_user.name As Client,  ost_ticket.ip_address As IP,  ost_department.name As Departament,  ost_staff.username As Staff,  ost_ticket.source As Source,  ost_ticket.created As DataOn,  ost_ticket.duedate As DueDate,  ost_ticket.closed As ClosedDate,  ost_ticket.status_id As STATUS,  ost_help_topic.topic  From ost_ticket  Join ost_staff On ost_staff.staff_id = ost_ticket.staff_id  Join ost_department On ost_ticket.dept_id = ost_department.id  Join ost_user_email On ost_ticket.user_id = ost_user_email.user_id  Join ost_user On ost_user_email.id = ost_user.id Inner Join ost_help_topic On ost_ticket.topic_id = ost_help_topic.topic_id;